package com.callback.moviebox.nativeapp;

import android.app.Activity;
import android.os.Bundle;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
  private final int BG=Color.rgb(10,10,16), PANEL=Color.rgb(22,22,31), WHITE=Color.rgb(242,242,246), MUTED=Color.rgb(154,154,174), RED=Color.rgb(229,9,20);
  private LinearLayout root, content, header;
  private EditText search;
  private String apiKey="";
  private final ExecutorService io=Executors.newSingleThreadExecutor();
  private final android.os.Handler main=new android.os.Handler();
  private String currentQuery="";
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility( View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY); apiKey=getPreferences(0).getString("tmdb_key",""); buildShell(); if(apiKey.isEmpty()) showSettings(); else loadHome();}
  private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
  private TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(WHITE);t.setTextSize(size);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
  private TextView button(String s,Runnable r){TextView t=text(s,16,true);t.setPadding(22,12,22,12);t.setFocusable(true);t.setBackground(shape(PANEL,10));t.setOnClickListener(v->r.run());t.setOnFocusChangeListener((v,f)->v.setBackground(shape(f?RED:PANEL,10)));return t;}
  private void buildShell(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);setContentView(root);header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(30,14,30,14);header.setBackgroundColor(BG);root.addView(header,new LinearLayout.LayoutParams(-1,68));TextView brand=text("MOVIEBOX",22,true);brand.setTextColor(RED);header.addView(brand);LinearLayout.LayoutParams spacer=new LinearLayout.LayoutParams(0,1,1);header.addView(new View(this),spacer);search=new EditText(this);search.setSingleLine(true);search.setHint("Search movies and TV shows");search.setHintTextColor(MUTED);search.setTextColor(WHITE);search.setTextSize(16);search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);search.setBackground(shape(PANEL,10));search.setPadding(18,8,18,8);header.addView(search,new LinearLayout.LayoutParams(310,46));search.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_SEARCH){searchFor(search.getText().toString());return true;}return false;});header.addView(button("⌂ Home",()->loadHome()));header.addView(button("⚙ Settings",()->showSettings()));ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));content=new LinearLayout(this);content.setOrientation(1);content.setPadding(30,16,30,40);scroll.addView(content);}
  private void clear(String title){content.removeAllViews();TextView h=text(title,27,true);h.setPadding(0,10,0,22);content.addView(h);}
  private void showMessage(String s){clear("MOVIEBOX");TextView m=text(s,18,false);content.addView(m);}
  private void showSettings(){clear("Settings");TextView l=text("TMDB API Key",17,true);content.addView(l);EditText key=new EditText(this);key.setSingleLine(true);key.setTextColor(WHITE);key.setHintTextColor(MUTED);key.setHint("Paste TMDB API key or read access token");key.setText(apiKey);key.setBackground(shape(PANEL,8));key.setPadding(16,12,16,12);content.addView(key,new LinearLayout.LayoutParams(620,54));content.addView(button("Save & Load Home",()->{apiKey=key.getText().toString().trim();getPreferences(0).edit().putString("tmdb_key",apiKey).apply();loadHome();}));}
  private JSONObject request(String path)throws Exception{URL u=new URL("https://api.themoviedb.org/3"+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);if(apiKey.length()>40)c.setRequestProperty("Authorization","Bearer "+apiKey);else u=new URL("https://api.themoviedb.org/3"+path+(path.contains("?")?"&":"?")+"api_key="+URLEncoder.encode(apiKey,"UTF-8"));if(!u.equals(c.getURL())){c.disconnect();c=(HttpURLConnection)u.openConnection();}c.setRequestProperty("Accept","application/json");int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);c.disconnect();if(code>=400)throw new Exception("TMDB HTTP "+code);return new JSONObject(out.toString("UTF-8"));}
  private void async(String path,java.util.function.Consumer<JSONObject> done){if(apiKey.isEmpty()){showSettings();return;}showMessage("Loading…");io.execute(()->{try{JSONObject data=request(path);main.post(()->done.accept(data));}catch(Exception e){main.post(()->showMessage("Could not load data. Check internet and TMDB API key.\n"+e.getMessage()));}});}
  private void loadHome(){async("/trending/all/week?language=en-US",data->{clear("Trending This Week");addResults(data);async("/movie/popular?language=en-US&page=1",d->{TextView h=text("Popular Movies",23,true);h.setPadding(0,24,0,14);content.addView(h);addResults(d);});});}
  private void searchFor(String q){if(q.trim().isEmpty())return;currentQuery=q;async("/search/multi?query="+enc(q)+"&include_adult=false&language=en-US&page=1",d->{clear("Search Results — "+q);addResults(d);});}
  private String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return s;}}
  private void addResults(JSONObject data){JSONArray a=data.optJSONArray("results");if(a==null||a.length()==0){content.addView(text("No results found.",17,false));return;}for(int i=0;i<a.length();i++){JSONObject item=a.optJSONObject(i);if(item==null)continue;String type=item.optString("media_type","movie");if(!type.equals("movie")&&!type.equals("tv"))type="movie";String name=item.optString("title",item.optString("name","Untitled"));String year=item.optString("release_date",item.optString("first_air_date",""));String id=item.optString("id");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(14,8,14,8);row.setBackground(shape(PANEL,8));row.setFocusable(true);row.setOnFocusChangeListener((v,f)->row.setBackground(shape(f?0xff292936:PANEL,8)));TextView poster=text("▶",24,true);poster.setGravity(Gravity.CENTER);poster.setBackground(shape(0xff252532,6));row.addView(poster,new LinearLayout.LayoutParams(70,94));LinearLayout info=new LinearLayout(this);info.setOrientation(1);info.setPadding(18,0,0,0);info.addView(text(name,18,true));info.addView(text((year.length()>=4?year.substring(0,4):"")+"   ★ "+item.optString("vote_average","—"),14,false));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("DETAILS  ›",14,true));final String media=type;row.setOnClickListener(v->openDetail(media,id));content.addView(row,new LinearLayout.LayoutParams(-1,112));View gap=new View(this);content.addView(gap,new LinearLayout.LayoutParams(1,8));}}
  private void openDetail(String type,String id){async("/"+type+"/"+id+"?language=en-US",d->{clear(d.optString("title",d.optString("name","Details")));content.addView(text("Overview",18,true));content.addView(text(d.optString("overview","No description available."),16,false));content.addView(text("Release: "+d.optString("release_date",d.optString("first_air_date","")),15,false));if(type.equals("tv")){content.addView(button("View Seasons / Episodes",()->loadSeasons(id,d.optInt("number_of_seasons",1))));}content.addView(button("Play",()->{Toast.makeText(this,"Choose a playable source from the native player integration.",Toast.LENGTH_LONG).show();}));content.addView(button("Back to results",()->{if(currentQuery.isEmpty())loadHome();else searchFor(currentQuery);}));});}
  private void loadSeasons(String id,int count){clear("Seasons");for(int s=1;s<=count;s++){final int season=s;content.addView(button("Season "+s,()->async("/tv/"+id+"/season/"+season+"?language=en-US",d->{clear("Season "+season);JSONArray eps=d.optJSONArray("episodes");if(eps!=null)for(int i=0;i<eps.length();i++){JSONObject ep=eps.optJSONObject(i);if(ep!=null)content.addView(text("Episode "+ep.optInt("episode_number")+"  •  "+ep.optString("name"),16,false));}content.addView(button("Back",()->loadSeasons(id,count)));})));}}
  @Override public boolean onKeyDown(int key,android.view.KeyEvent event){if(key==KeyEvent.KEYCODE_BACK){if(search.hasFocus()){search.clearFocus();return true;}loadHome();return true;}return super.onKeyDown(key,event);}
  @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
